mapper.update:
UPDATE sys_flow_task_candidate
SET status = 1, source = #{source}, update_time = #{updateTime}
WHERE tenant_id = #{tenantId}
  AND task_id = #{taskId}
  AND candidate_type = #{candidateType}
  AND candidate_value = #{candidateValue}

UPDATE sys_flow_task_candidate
SET status = 0, update_time = #{updateTime}
WHERE tenant_id = #{tenantId}
  AND task_id = #{taskId}
  AND candidate_type = #{candidateType}
  AND candidate_value = #{candidateValue}
  AND status = 1

UPDATE sys_flow_task_candidate
SET status = 0,
    operator_id = #{operatorId},
    reason = #{reason},
    idempotency_key = COALESCE(#{idempotencyKey}, idempotency_key),
    request_digest = COALESCE(#{requestDigest}, request_digest),
    update_time = #{updateTime}
WHERE tenant_id = #{tenantId}
  AND task_id = #{taskId}
  AND candidate_type = #{candidateType}
  AND candidate_value = #{candidateValue}
  AND status = 1

mapper.select:
SELECT COUNT(1)
FROM sys_flow_task_candidate
WHERE tenant_id = #{tenantId}
  AND task_id = #{taskId}
  AND candidate_type = #{candidateType}
  AND candidate_value = #{candidateValue}
  AND status = 1
